import { writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dirname, "..");
const fixturesDir = join(root, "e2e", "fixtures");

mkdirSync(fixturesDir, { recursive: true });

// 1x1 valid PNG (67 bytes)
const pngBase64 =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==";

// 1x1 valid JPEG
const jpegBase64 =
  "";

function writeBase64(filename, b64) {
  const buffer = Buffer.from(b64, "base64");
  const dest = join(fixturesDir, filename);
  writeFileSync(dest, buffer);
  console.log(`Created ${dest} (${buffer.length} bytes)`);
}

writeBase64("room.png", pngBase64);
writeBase64("house.jpg", jpegBase64);
writeBase64("floor-plan.png", pngBase64);
writeBase64("facade.png", pngBase64);
